// Spider-Man 2 "pool fix": typed access to the 2 GB mesh pool made raw (LAYOVER_POOL_FIX, default on).
//
// D3DMetal on M1-M4 backs a typed buffer view with a Metal texture buffer, which is capped at 2^28
// elements. The game views its 2046 MB "ManagedBuffer" pool through typed R32_UINT SRVs/UAVs of
// 536,346,624 elements, so every typed READ at element 2^28+ returns 0 (skinned models stored high stay
// in bind pose: T-pose) and every typed WRITE there is LOST. The symbiote's spline meshes (Harry's and
// Venom's tendrils) are generated by two compute shaders that write their triangle indices into the
// pool through such a UAV every frame; above 1 GB the writes vanish and the tendrils are drawn from
// whatever bytes were there before: spikes, sheets, giant triangles that take the GPU seconds per
// frame (the 60 -> 2 fps collapses of 2026-10-24/26/31, always during Harry's symbiote scenes).
//
// sm2_skin.c already keeps skinned-model and impostor DATA below 1 GB (reads). This module removes
// the limit itself, the way macprotips/SpiderMan2Fix (public domain) does it:
//   1. typed 32-bit buffer SRVs/UAVs wider than 2^28 elements are created as raw views
//      (R32_TYPELESS + RAW flag): a raw view is a plain Metal buffer, no width limit;
//   2. the four game shaders that use those views are swapped, at pipeline creation and by hash, for
//      copies whose typed loads/stores are raw loads/stores at index*4 (the same bytes, same results):
//        3d50acdb571dce22 CS_ModelSkinning                 (SRV t1)
//        14902794dd7134e4 vertex morph                     (SRV t0)
//        9538ca33c087a84c CS_AnimSplineMeshGenIndices      (UAV u1)  <- the symbiote
//        125a4957ab64d24d CS_AnimSplineMeshGenIndicesFinalize (UAV u1)
//      The copies are built on this Mac from the game's own exe by `layover sm2-shaders` (dxc -dumpbin,
//      text rewrite, dxa, dxv) into <LAYOVER_POOL_SHADERS>\sm2-pool-<hash>.dxil (default: beside this
//      DLL). Shader hashes are 64-bit FNV-1 (multiply, then xor) over the DXBC container, vkd3d-proton's.
// Both halves go together: a raw view under an unmodified typed shader would read garbage. So the fix
// is active only when the exe is the known build (sm2_known_build) AND all four files load; otherwise
// nothing is changed and the stats line reports the wide typed views seen ("hazard" count).
#include <windows.h>
#include <d3d12.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

void shim_note(const char *fmt, ...);
int sm2_known_build(void);

#define WIDE_VIEW (1u << 28)
#define N_SHADERS 4
static const UINT64 pool_hashes[N_SHADERS] = { 0x3d50acdb571dce22ull, 0x14902794dd7134e4ull, 0x9538ca33c087a84cull, 0x125a4957ab64d24dull };
static const char *pool_names[N_SHADERS] = { "CS_ModelSkinning", "vertex morph", "CS_AnimSplineMeshGenIndices", "CS_AnimSplineMeshGenIndicesFinalize" };
static struct { UINT64 hash; void *data; SIZE_T size; volatile LONG used; } shaders[N_SHADERS];
static int pool_active, pool_wanted = 1, pool_loaded; static const char *pool_reason = "not Spider-Man 2";
static volatile LONG c_wide_srv, c_wide_uav, c_raw_srv, c_raw_uav, c_replaced, c_replace_failed;
static char shader_dir[MAX_PATH];

UINT64 pool_fnv1(const void *p, SIZE_T n)
{
    const UINT8 *b = p; UINT64 h = 0xcbf29ce484222325ull; SIZE_T i;
    for (i = 0; i < n; i++) h = (h * 0x100000001b3ull) ^ b[i];
    return h;
}

static void *read_whole(const char *path, SIZE_T *size)
{
    FILE *f = fopen(path, "rb"); long n; void *d = NULL;
    *size = 0;
    if (!f) return NULL;
    if (!fseek(f, 0, SEEK_END) && (n = ftell(f)) > 0 && !fseek(f, 0, SEEK_SET) && (d = malloc((size_t)n))) {
        if (fread(d, 1, (size_t)n, f) == (size_t)n) *size = (SIZE_T)n; else { free(d); d = NULL; }
    }
    fclose(f);
    return d;
}

void pool_fix_install(HINSTANCE self)
{
    char v[32], exepath[MAX_PATH]; const char *base; int i, missing = 0;
    GetModuleFileNameA(NULL, exepath, sizeof exepath); base = strrchr(exepath, '\\'); base = base ? base + 1 : exepath;
    if (_stricmp(base, "Spider-Man2.exe")) return;
    if (GetEnvironmentVariableA("LAYOVER_POOL_FIX", v, sizeof v) >= 1) pool_wanted = atoi(v) != 0;
    pool_reason = "disabled (LAYOVER_POOL_FIX=0)";
    if (!pool_wanted) { shim_note("pool fix: off (LAYOVER_POOL_FIX=0); wide typed views are only counted"); return; }
    pool_reason = "game build changed";
    if (!sm2_known_build()) { shim_note("pool fix: OFF, the game build is not the one the shaders were rewritten for"); return; }
    pool_reason = "shaders not built";
    if (!GetEnvironmentVariableA("LAYOVER_POOL_SHADERS", shader_dir, sizeof shader_dir) || !shader_dir[0]) {
        char *p; GetModuleFileNameA(self, shader_dir, sizeof shader_dir); p = strrchr(shader_dir, '\\'); if (p) *p = 0;
    }
    for (i = 0; i < N_SHADERS; i++) {
        char path[MAX_PATH + 64]; SIZE_T size; void *d; UINT64 h;
        snprintf(path, sizeof path, "%s\\sm2-pool-%016llx.dxil", shader_dir, (unsigned long long)pool_hashes[i]);
        d = read_whole(path, &size);
        if (!d || size < 32 || memcmp(d, "DXBC", 4)) { shim_note("pool fix: %s missing or not a DXBC container (%s)", path, pool_names[i]); free(d); missing++; continue; }
        h = pool_fnv1(d, size);
        shaders[i].hash = pool_hashes[i]; shaders[i].data = d; shaders[i].size = size; pool_loaded++;
        shim_note("pool fix: loaded %s (%llu bytes, hash %016llx) for %s", path, (unsigned long long)size, (unsigned long long)h, pool_names[i]);
    }
    if (missing) { shim_note("pool fix: OFF, %d of %d rewritten shaders missing; run `layover sm2-shaders` (needs the DXC tools: tools/dev/build-dxc.sh). Wide typed views are only counted.", missing, N_SHADERS); return; }
    pool_active = 1;
    shim_note("pool fix: ON. Typed R32 buffer views wider than 2^28 elements become raw views and %d shaders are replaced by their raw-access copies from %s", N_SHADERS, shader_dir);
}

int pool_fix_active(void) { return pool_active; }

// SRV: returns 1 and fills *out when the view must be created as raw instead
int pool_fix_srv(const D3D12_SHADER_RESOURCE_VIEW_DESC *d, D3D12_SHADER_RESOURCE_VIEW_DESC *out)
{
    if (!d || d->ViewDimension != D3D12_SRV_DIMENSION_BUFFER || d->Buffer.NumElements <= WIDE_VIEW || (d->Buffer.Flags & D3D12_BUFFER_SRV_FLAG_RAW)) return 0;
    if (d->Format != DXGI_FORMAT_R32_UINT && d->Format != DXGI_FORMAT_R32_SINT && d->Format != DXGI_FORMAT_R32_FLOAT) return 0;
    InterlockedIncrement(&c_wide_srv);
    if (!pool_active) return 0;
    *out = *d; out->Format = DXGI_FORMAT_R32_TYPELESS; out->Buffer.Flags |= D3D12_BUFFER_SRV_FLAG_RAW; out->Buffer.StructureByteStride = 0;
    if (InterlockedIncrement(&c_raw_srv) <= 4) shim_note("pool fix: wide typed SRV (fmt %u, first %llu, %u elements) created as a raw view", (unsigned)d->Format, (unsigned long long)d->Buffer.FirstElement, d->Buffer.NumElements);
    return 1;
}

int pool_fix_uav(ID3D12Resource *counter, const D3D12_UNORDERED_ACCESS_VIEW_DESC *d, D3D12_UNORDERED_ACCESS_VIEW_DESC *out)
{
    if (!d || d->ViewDimension != D3D12_UAV_DIMENSION_BUFFER || d->Buffer.NumElements <= WIDE_VIEW || counter || (d->Buffer.Flags & D3D12_BUFFER_UAV_FLAG_RAW)) return 0;
    if (d->Format != DXGI_FORMAT_R32_UINT && d->Format != DXGI_FORMAT_R32_SINT && d->Format != DXGI_FORMAT_R32_FLOAT) return 0;
    InterlockedIncrement(&c_wide_uav);
    if (!pool_active) return 0;
    *out = *d; out->Format = DXGI_FORMAT_R32_TYPELESS; out->Buffer.Flags |= D3D12_BUFFER_UAV_FLAG_RAW; out->Buffer.StructureByteStride = 0; out->Buffer.CounterOffsetInBytes = 0;
    if (InterlockedIncrement(&c_raw_uav) <= 4) shim_note("pool fix: wide typed UAV (fmt %u, first %llu, %u elements) created as a raw view", (unsigned)d->Format, (unsigned long long)d->Buffer.FirstElement, d->Buffer.NumElements);
    return 1;
}

// the rewritten copy of a compute shader, if it is one of the four (NULL otherwise)
const void *pool_fix_replacement(const void *code, SIZE_T len, SIZE_T *out_len, const char **name)
{
    UINT64 h; int i;
    if (!pool_active || !code || len < 32) return NULL;
    h = pool_fnv1(code, len);
    for (i = 0; i < N_SHADERS; i++) if (shaders[i].hash == h) { *out_len = shaders[i].size; if (name) *name = pool_names[i]; InterlockedIncrement(&shaders[i].used); return shaders[i].data; }
    return NULL;
}
void pool_fix_note_result(int ok) { if (ok) InterlockedIncrement(&c_replaced); else InterlockedIncrement(&c_replace_failed); }

// Byte size of one D3D12 pipeline-state-stream subobject (type word + alignment padding + payload,
// rounded up to 8) in the 64-bit layout, 0 for an unknown type.
SIZE_T pool_stream_sub_size(UINT type)
{
    SIZE_T size, align = 4;
    switch (type) {
    case 0: size = 8; align = 8; break;                              // root signature (pointer)
    case 1: case 2: case 3: case 4: case 5: case 6: case 24: case 25: size = 16; align = 8; break;   // shader bytecode
    case 7: size = 32; align = 8; break;                             // stream output
    case 8: size = 328; break;                                       // blend
    case 9: size = 4; break;                                         // sample mask
    case 10: size = 44; break;                                       // rasterizer
    case 11: size = 52; break;                                       // depth stencil
    case 12: size = 16; align = 8; break;                            // input layout
    case 13: size = 4; break;                                        // IB strip cut
    case 14: size = 4; break;                                        // topology
    case 15: size = 36; break;                                       // RT formats
    case 16: size = 4; break;                                        // DS format
    case 17: size = 8; break;                                        // sample desc
    case 18: size = 4; break;                                        // node mask
    case 19: size = 16; align = 8; break;                            // cached PSO
    case 20: size = 4; break;                                        // flags
    case 21: size = 56; break;                                       // depth stencil 1
    case 22: size = 24; align = 8; break;                            // view instancing
    case 26: size = 60; break;                                       // depth stencil 2
    case 27: size = 44; break;                                       // rasterizer 1
    case 28: size = 40; break;                                       // rasterizer 2
    default: return 0;
    }
    { SIZE_T off = (4 + align - 1) & ~(align - 1); return (off + size + 7) & ~(SIZE_T)7; }
}
// Offset of the CS subobject's payload (the D3D12_SHADER_BYTECODE) in a stream, or -1.
long pool_stream_cs_offset(const void *stream, SIZE_T size)
{
    const UINT8 *b = stream; SIZE_T off = 0;
    if (!b) return -1;
    while (off + 4 <= size) {
        UINT type = *(const UINT *)(b + off); SIZE_T sub = pool_stream_sub_size(type);
        if (!sub || size - off < sub) return -1;
        if (type == 5) return (long)(off + 8);
        off += sub;
    }
    return -1;
}

void pool_fix_stats(char *out, size_t cap)
{
    if (pool_active) snprintf(out, cap, "pool-fix: ON shaders replaced %ld (skin %ld morph %ld symbiote %ld+%ld) failed %ld | raw views srv %ld uav %ld", c_replaced, shaders[0].used, shaders[1].used, shaders[2].used, shaders[3].used, c_replace_failed, c_raw_srv, c_raw_uav);
    else snprintf(out, cap, "pool-fix: off (%s) | wide typed views seen srv %ld uav %ld (hazard: reads above 1 GB return 0, writes are lost)", pool_reason, c_wide_srv, c_wide_uav);
}
